        "example": "Accessing request data.",
        "code": "app.post('/api/users', (req, res) => {\n    console.log(req.method);  // 'POST'\n    console.log(req.headers); // { 'user-agent': '...', 'authorization': '...' }\n    console.log(req.ip);      // IP address of the client\n});",
